  /* ডোজের লেখা: [সকাল, দুপুর, রাত] → ১+০+১ */
  function patText(p) { return p.join('+').replace(/\d/g, function (d) { return '০১২৩৪৫৬৭৮৯'[d]; }); }
  function qtyOf(l) { if (l.fixedQty != null) return l.fixedQty; if (!l.pat || l.days == null) return null; return l.pat.reduce(function (a, b) { return a + b; }, 0) * l.days; }
  function rxTotal(lines) { return lines.reduce(function (s, l) { var q = qtyOf(l), p = PRODUCTS[l.p]; return s + (q == null ? 0 : q * p.mrp); }, 0); }
