    /* ডিকয়ের মধ্যে সবচেয়ে কাছাকাছি নামেরগুলো আগে (ভুল করার সম্ভাবনা বাড়ায়): একই জেনেরিক বা একই ট্যাগ */
    decoyIds.sort(function (a, b) { var sa = need.some(function (n) { return PRODUCTS[n].g.split(' ')[0] === PRODUCTS[a].g.split(' ')[0] || PRODUCTS[n].tag === PRODUCTS[a].tag; }) ? 0 : 1, sb = need.some(function (n) { return PRODUCTS[n].g.split(' ')[0] === PRODUCTS[b].g.split(' ')[0] || PRODUCTS[n].tag === PRODUCTS[b].tag; }) ? 0 : 1; return sa - sb || rnd() - .5; });
    var total = 10, k = 0; while (boxes.length < total && k < decoyIds.length) { boxes.push({ p: decoyIds[k++], exp: addMonths(now, 12 + Math.floor(rnd() * 12)), batch: 'B-' + (1000 + Math.floor(rnd() * 8999)), need: false }); }
    for (var i = boxes.length - 1; i > 0; i--) { var j = Math.floor(rnd() * (i + 1)), t = boxes[i]; boxes[i] = boxes[j]; boxes[j] = t; }
